"""Verifier for quarter-plane-tails (generated by gen_tests.py from test_outputs_head.py).

The submitted program /root/qtails/tails.py is run once, as the unprivileged user `sandbox`,
on the 31 walks of heldout_walks.json. Its output is compared with expected.json.
Reward 1 iff every test passes.
"""
import json
import os
import shutil
import signal
import stat
import subprocess
import sys
import tempfile
from pathlib import Path

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE))
import qtails_check as QC  # noqa: E402

PROGRAM_DIR = "/root/qtails"
PROGRAM = PROGRAM_DIR + "/tails.py"
TIME_LIMIT = 1800          # seconds of wall clock for the whole file (stated in the instruction)
SANDBOX_USER = "sandbox"
LOG_DIR = "/logs/verifier"
HELDOUT = HERE / "heldout_walks.json"
EXPECTED = HERE / "expected.json"

EXP = json.loads(EXPECTED.read_text())
IDS = [w["id"] for w in json.loads(HELDOUT.read_text())["walks"]]
_STATE = {}


def _scan_submission():
    """lstat-walk of the submission: reject symbolic links and special files, delete byte code."""
    problems = []
    try:
        st = os.lstat(PROGRAM_DIR)
    except FileNotFoundError:
        return ["%s does not exist" % PROGRAM_DIR]
    if not stat.S_ISDIR(st.st_mode):
        return ["%s is not a directory" % PROGRAM_DIR]
    stack = [PROGRAM_DIR]
    while stack:
        d = stack.pop()
        with os.scandir(d) as it:
            entries = list(it)
        for e in entries:
            m = os.lstat(e.path).st_mode
            if stat.S_ISLNK(m):
                problems.append("symbolic link in the submission: %s" % e.path)
            elif stat.S_ISDIR(m):
                if e.name == "__pycache__":
                    shutil.rmtree(e.path)
                else:
                    stack.append(e.path)
            elif stat.S_ISREG(m):
                if e.name.endswith(".pyc"):
                    os.unlink(e.path)
            else:
                problems.append("special file in the submission: %s" % e.path)
    try:
        pm = os.lstat(PROGRAM).st_mode
        if not stat.S_ISREG(pm):
            problems.append("%s is not a regular file" % PROGRAM)
    except FileNotFoundError:
        problems.append("%s does not exist" % PROGRAM)
    return problems


def _chown_tree(path, uid, gid):
    os.lchown(path, uid, gid)
    for root, dirs, files in os.walk(path, followlinks=False):
        for n in dirs + files:
            os.lchown(os.path.join(root, n), uid, gid)


def _read_regular(path):
    """read an agent-written file without following links: lstat, S_ISREG, O_NOFOLLOW, fstat."""
    st = os.lstat(path)
    if not stat.S_ISREG(st.st_mode):
        raise ValueError("output is not a regular file")
    fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
    try:
        fs = os.fstat(fd)
        if not stat.S_ISREG(fs.st_mode):
            raise ValueError("output is not a regular file")
        if fs.st_size > QC.MAX_OUTPUT_BYTES:
            raise ValueError("output larger than %d bytes" % QC.MAX_OUTPUT_BYTES)
        chunks, total = [], 0
        while True:
            b = os.read(fd, 65536)
            if not b:
                break
            total += len(b)
            if total > QC.MAX_OUTPUT_BYTES:
                raise ValueError("output larger than %d bytes" % QC.MAX_OUTPUT_BYTES)
            chunks.append(b)
        return b"".join(chunks)
    finally:
        os.close(fd)


def _kill_sandbox(pgid=None):
    if pgid is not None:
        try:
            os.killpg(pgid, signal.SIGKILL)
        except (ProcessLookupError, PermissionError):
            pass
    subprocess.run(["pkill", "-9", "-u", SANDBOX_USER], check=False)


def run_program():
    if "run" in _STATE:
        return _STATE["run"]
    import pwd
    res = {"status": None, "returncode": None, "problems": [], "data": None}
    res["problems"] = _scan_submission()
    if res["problems"]:
        res["status"] = "invalid submission"
        _finish(res)
        return res
    pw = pwd.getpwnam(SANDBOX_USER)
    _chown_tree(PROGRAM_DIR, pw.pw_uid, pw.pw_gid)
    os.chmod("/root", 0o711)
    io_dir = tempfile.mkdtemp(prefix="qtails_io_", dir="/var/tmp")
    work = tempfile.mkdtemp(prefix="qtails_run_", dir="/var/tmp")
    proc = None
    try:
        for d in (io_dir, work):
            os.chown(d, pw.pw_uid, pw.pw_gid)
            os.chmod(d, 0o700)
        inp = os.path.join(io_dir, "input.json")
        out = os.path.join(io_dir, "output.json")
        with open(inp, "wb") as f:
            f.write(HELDOUT.read_bytes())
        os.chown(inp, pw.pw_uid, pw.pw_gid)
        env = {"PATH": "/usr/local/bin:/usr/bin:/bin", "HOME": work, "TMPDIR": work,
               "PYTHONDONTWRITEBYTECODE": "1", "LANG": "C.UTF-8", "PYTHONHASHSEED": "0"}
        proc = subprocess.Popen(["python3", PROGRAM, inp, out], cwd=work, env=env,
                                user=pw.pw_uid, group=pw.pw_gid, extra_groups=[],
                                start_new_session=True, stdin=subprocess.DEVNULL,
                                stdout=subprocess.DEVNULL, stderr=subprocess.PIPE)
        try:
            _, err = proc.communicate(timeout=TIME_LIMIT)
            res["status"] = "finished"
            res["returncode"] = proc.returncode
            res["stderr_tail"] = err[-3000:].decode("utf-8", "replace")
        except subprocess.TimeoutExpired:
            res["status"] = "timeout"
        _kill_sandbox(proc.pid)
        if res["status"] == "finished":
            try:
                raw = _read_regular(out)
                res["data"] = QC.parse_strict(raw)
            except FileNotFoundError:
                res["problems"].append("no output file")
            except Exception as exc:
                res["problems"].append("output rejected: %s" % exc)
    finally:
        _kill_sandbox(proc.pid if proc else None)
        shutil.rmtree(work, ignore_errors=True)
        shutil.rmtree(io_dir, ignore_errors=True)
    _finish(res)
    return res


def _finish(res):
    # intermediates for audits (no wall time, so repeated runs are byte-identical)
    inter = {"status": res["status"], "returncode": res["returncode"], "problems": res["problems"],
             "structure": QC.check_structure(res["data"], IDS) if res["data"] is not None else None,
             "walks": {}}
    for wid in IDS:
        ok, probs, rec = QC.judge_walk(res["data"], wid, EXP[wid])
        inter["walks"][wid] = {"ok": ok, "problems": probs, "fields": rec}
    res["inter"] = inter
    try:
        with open(os.path.join(LOG_DIR, "intermediates.json"), "w") as f:
            json.dump(inter, f, indent=1, sort_keys=True)
    except OSError:
        pass
    _STATE["run"] = res


def walk_verdict(wid):
    res = run_program()
    if res["data"] is None:
        return False, ["no usable output (%s)" % "; ".join(res["problems"] or [str(res["status"])])]
    w = res["inter"]["walks"][wid]
    return w["ok"], w["problems"]


def test_contract():
    """The submission is a symlink-free directory with a regular tails.py; the program finishes
    within 1800 s with exit status 0 and writes a regular, strict-JSON output file whose keys are
    exactly the input walk ids."""
    res = run_program()
    assert not res["problems"], "submission/output: " + "; ".join(res["problems"])
    assert res["status"] == "finished", "program run: %s (limit %d s)" % (res["status"], TIME_LIMIT)
    assert res["returncode"] == 0, "program exit status: %r; stderr tail: %s" % (res["returncode"], res.get("stderr_tail", ""))
    assert isinstance(res["data"], dict), "output: not a JSON object"
    st = res["inter"]["structure"]
    assert not st, "output keys: " + "; ".join(st)
    missing = [w for w in IDS if w not in res["data"]]
    assert not missing, "output keys: walks missing: %s" % missing[:5]


def test_w01():
    """Walk w01: for all four sequences, kappa equals the exact value and rho is within
    relative error 1e-9 of the exact value, with both fields well formed."""
    ok, probs = walk_verdict("w01")
    assert ok, "walk w01: " + "; ".join(probs)


